// JS wrapper
import { NativeModules, NativeEventEmitter } from 'react-native';
const { ClipboardModule } = NativeModules;
const ce = new NativeEventEmitter(ClipboardModule);

export const copyText = (text) => ClipboardModule.copyText(text);
export const getClipboard = () => ClipboardModule.getClipboard();
export const onClipboardChange = (cb) => ce.addListener('clipboardChanged', cb);
